public class MainActivity extends Activity {
 int dayLevel,nightLevel;String nightStart,nightEnd;TextView dayValue,nightValue,status,detail,compatibility;Button startTime,endTime,nightTest,dayTest;Switch enabled;boolean updating=false,supported=false;Handler handler=new Handler();
 SharedPreferences prefs(){return getSharedPreferences("schedule",0);}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 GradientDrawable surface(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(9));return d;}
 StateListDrawable buttonBackground(){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},surface(0xff626dad));d.addState(new int[]{android.R.attr.state_pressed},surface(0xff505d99));d.addState(new int[]{},surface(0xffffffff));return d;}
 Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[]{android.R.attr.state_pressed},new int[]{}},new int[]{Color.WHITE,Color.WHITE,0xff1c4c77}));b.setTextSize(15);b.setAllCaps(false);b.setBackground(buttonBackground());b.setMinHeight(dp(42));b.setPadding(dp(12),dp(3),dp(12),dp(3));b.setOnClickListener(v->{try{action.run();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}});return b;}
 void addButton(LinearLayout parent,Button b){b.setMinHeight(dp(43));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(9);parent.addView(b,p);}
 LinearLayout card(String title){LinearLayout c=column();c.setPadding(dp(20),dp(16),dp(20),dp(16));c.setBackground(surface(0xfff0efff));TextView t=text(title,20,0xff26334b);t.setTypeface(null,Typeface.BOLD);c.addView(t);return c;}
 @Override public void onCreate(Bundle state){super.onCreate(state);SharedPreferences p=prefs();dayLevel=p.getInt("day",30);nightLevel=p.getInt("night",10);nightStart=p.getString("start","21:00");nightEnd=p.getString("end","09:00");
  boolean compact=getResources().getConfiguration().screenWidthDp<800;
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfffafaff);LinearLayout root=column();root.setPadding(dp(compact?20:40),dp(24),dp(compact?20:40),dp(20));scroll.addView(root,new ScrollView.LayoutParams(-1,-2));setContentView(scroll);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);ImageView mark=new ImageView(this);mark.setImageResource(getResources().getIdentifier("ww_mark","drawable",getPackageName()));LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(dp(100),dp(48));mp.rightMargin=dp(12);header.addView(mark,mp);header.addView(new View(this),new LinearLayout.LayoutParams(0,dp(48),1));enabled=new Switch(this);enabled.setText("Расписание  ");enabled.setTextSize(18);enabled.setTextColor(0xff26334b);enabled.setChecked(p.getBoolean("enabled",false));enabled.setPadding(dp(18),0,0,0);enabled.setFocusable(true);header.addView(enabled,new LinearLayout.LayoutParams(dp(265),dp(48)));root.addView(header);
  if(getResources().getConfiguration().screenWidthDp<440){header.setOrientation(1);header.setGravity(Gravity.LEFT);}
  LinearLayout intro=new LinearLayout(this);intro.setGravity(Gravity.CENTER_VERTICAL);intro.setPadding(0,dp(6),0,dp(6));TextView explanation=text("Яркость телевизора · день и ночь по времени",16,0xff4e6b81);if(compact)intro.setOrientation(1);intro.addView(explanation,compact?new LinearLayout.LayoutParams(-1,-2):new LinearLayout.LayoutParams(0,-2,1));intro.addView(button("Совместимость",()->connect()),compact?new LinearLayout.LayoutParams(-1,-2):new LinearLayout.LayoutParams(dp(175),-2));root.addView(intro,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout cards=new LinearLayout(this);if(compact)cards.setOrientation(1);LinearLayout levels=card("Уровни яркости"),times=card("Время переключения");times.setBackground(surface(0xffedf8f7));LinearLayout.LayoutParams left=compact?new LinearLayout.LayoutParams(-1,-2):new LinearLayout.LayoutParams(0,-2,1);if(!compact)left.rightMargin=dp(16);cards.addView(levels,left);LinearLayout.LayoutParams right=compact?new LinearLayout.LayoutParams(-1,-2):new LinearLayout.LayoutParams(0,-2,1);if(compact)right.topMargin=dp(16);cards.addView(times,right);root.addView(cards);
  dayValue=levelRow(levels,"День",true);nightValue=levelRow(levels,"Ночь",false);
  nightTest=button("Проверить ночную яркость",()->{save();ScheduleService.start(this,"night");});dayTest=button("Вернуть дневную яркость",()->{save();ScheduleService.start(this,"day");});addButton(levels,nightTest);addButton(levels,dayTest);
  startTime=button("Ночной режим с "+nightStart,()->pickTime(true));endTime=button("Дневной режим с "+nightEnd,()->pickTime(false));addButton(times,startTime);addButton(times,endTime);addButton(times,button("Сохранить настройки",()->{save();if(prefs().getBoolean("enabled",false))ScheduleService.start(this,"start");Toast.makeText(this,"Настройки сохранены",Toast.LENGTH_SHORT).show();}));addButton(times,button("Отключить и вернуть дневную яркость",()->{save();ScheduleService.start(this,"stop");updating=true;enabled.setChecked(false);updating=false;}));
  status=text("",18,0xff1b7955);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(12);root.addView(status,sp);detail=text("",14,0xff4e6b81);root.addView(detail);compatibility=text("Проверяю совместимость прошивки…",13,0xff4e6b81);root.addView(compatibility);
  TextView note=text("Управление аппаратной подсветкой без открытия меню. Поддержка зависит от прошивки. Телевизор из сна приложение не включает.",12,0xff586f7c);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(6);root.addView(note,np);
  enabled.setOnCheckedChangeListener((b,on)->{if(updating)return;try{if(on){if(!supported)throw new IllegalStateException("Сначала подтвердите совместимость прошивки");if(!ScheduleService.canSchedule(this))throw new IllegalStateException("Откройте «Совместимость» и разрешите точные будильники");}save();ScheduleService.start(this,on?"start":"stop");}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();refresh();}});refresh();enabled.requestFocus();checkCompatibility(null);if(p.getBoolean("enabled",false))try{ScheduleService.start(this,"wake");}catch(RuntimeException e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();refresh();}
 }
 void connect(){
  if(prefs().getBoolean("working",false)){Toast.makeText(this,"Дождитесь завершения изменения яркости",Toast.LENGTH_LONG).show();return;}
  AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle("Совместимость телевизора").setMessage("Проверяю интерфейс аппаратной подсветки…").setPositiveButton("Закрыть",null);
  if(!ScheduleService.canSchedule(this))builder.setNeutralButton("Разрешить таймеры",(d,w)->{try{Intent request=new Intent("android.settings.REQUEST_SCHEDULE_EXACT_ALARM",android.net.Uri.parse("package:"+getPackageName()));startActivity(request);}catch(Exception e){Toast.makeText(this,"Откройте системные настройки → Приложения → Особый доступ → Будильники и напоминания",Toast.LENGTH_LONG).show();}});
  AlertDialog dialog=builder.create();dialog.show();checkCompatibility(dialog);
 }
 void checkCompatibility(AlertDialog dialog){new Thread(()->{String result;boolean found=false;try{int value=TclBrightness.read(this);String backend=TclBrightness.describe(this);found=true;result="Интерфейс найден: "+backend+". Подсветка: "+value+" / 100. "+(TclBrightness.writeVerified(this)?"Изменение и чтение уровня подтверждены на этой прошивке.":"Чтение работает. Изменение ещё не проверено — используйте кнопку проверки ночной яркости.");}catch(Exception e){result=e.getMessage();}final boolean available=found;final String message=result;handler.post(()->{if(isFinishing())return;supported=available;compatibility.setText((available?"Интерфейс подсветки доступен":"Прошивка не поддерживается")+" · "+Build.MANUFACTURER+" "+Build.MODEL+" · Android "+Build.VERSION.RELEASE);if(dialog!=null&&dialog.isShowing())dialog.setMessage(Build.MANUFACTURER+" "+Build.MODEL+" · Android "+Build.VERSION.RELEASE+"\n\n"+message+"\n\n"+(ScheduleService.canSchedule(this)?"Точные таймеры разрешены.":"Для расписания нужно разрешить точные будильники."));refresh();});}).start();}
 TextView levelRow(LinearLayout parent,String label,boolean day){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView t=text(label,17,0xff3e5872);t.setGravity(Gravity.CENTER_VERTICAL);row.addView(t,new LinearLayout.LayoutParams(0,dp(47),1));TextView value=text(""+(day?dayLevel:nightLevel)+" / 100",18,0xff205fa8);value.setGravity(Gravity.CENTER);Button minus=button("−5",()->changeLevel(day,-5));Button plus=button("+5",()->changeLevel(day,5));row.addView(minus,new LinearLayout.LayoutParams(dp(54),dp(38)));row.addView(value,new LinearLayout.LayoutParams(dp(88),dp(47)));row.addView(plus,new LinearLayout.LayoutParams(dp(54),dp(38)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(51));p.topMargin=dp(9);parent.addView(row,p);return value;}
 void changeLevel(boolean day,int delta){if(day){dayLevel=Math.max(1,Math.min(100,dayLevel+delta));dayValue.setText(dayLevel+" / 100");}else{nightLevel=Math.max(1,Math.min(100,nightLevel+delta));nightValue.setText(nightLevel+" / 100");}}
 void pickTime(boolean start){String[] parts=(start?nightStart:nightEnd).split(":");TimePickerDialog dialog=new TimePickerDialog(this,android.R.style.Theme_Holo_Light_Dialog,(view,h,m)->{String value=String.format(Locale.ROOT,"%02d:%02d",h,m);if(start){nightStart=value;startTime.setText("Ночной режим с "+value);}else{nightEnd=value;endTime.setText("Дневной режим с "+value);}},Integer.parseInt(parts[0]),Integer.parseInt(parts[1]),true);dialog.setTitle(start?"Начало ночного режима":"Возврат дневной яркости");dialog.show();}
 void save(){if(nightStart.equals(nightEnd))throw new IllegalArgumentException("Время начала и окончания должно отличаться");prefs().edit().putInt("day",dayLevel).putInt("night",nightLevel).putString("start",nightStart).putString("end",nightEnd).apply();}
 Runnable poll=new Runnable(){public void run(){refresh();handler.postDelayed(this,1000);}};
 void setTextIfChanged(TextView view,String value){if(!value.equals(view.getText().toString()))view.setText(value);}
 void refresh(){if(status==null)return;SharedPreferences p=prefs();nightTest.setEnabled(supported&&!p.getBoolean("working",false));dayTest.setEnabled(supported&&!p.getBoolean("working",false));enabled.setEnabled(supported||p.getBoolean("enabled",false));updating=true;enabled.setChecked(p.getBoolean("enabled",false));updating=false;String state=p.getBoolean("enabled",false)?"Расписание включено":"Расписание выключено";if(p.getBoolean("working",false))state+=" · меняю яркость…";setTextIfChanged(status,state);String error=p.getString("lastError","");int color=error.isEmpty()?0xff1b7955:0xffa73529;if(status.getCurrentTextColor()!=color)status.setTextColor(color);if(!error.isEmpty()){setTextIfChanged(detail,"Ошибка: "+p.getString("result",error));}else{long at=p.getLong("lastSuccess",0);setTextIfChanged(detail,at==0?"Яркость ещё не проверена": "Последняя проверенная яркость: "+p.getInt("lastActual",0)+" / 100 · "+new SimpleDateFormat("HH:mm:ss",Locale.ROOT).format(new Date(at)));}}
 @Override public void onResume(){super.onResume();handler.post(poll);}@Override public void onPause(){handler.removeCallbacks(poll);super.onPause();}
}
